describe("Payroll retained command transport", () => {
  it("retains the exact key through lost response, malformed success and missing acknowledgement", async () => {
    const seen: string[] = [], send = vi.fn(async (_url: RequestInfo | URL, init?: RequestInit) => {
      seen.push(new Headers(init?.headers).get("Idempotency-Key")!);
      if (seen.length === 1) throw Error("Lost response after commit");
      if (seen.length === 2) return new Response("truncated", {status: 200});
      if (seen.length === 3) return Response.json({data: null});
      return Response.json({data: {id: "run", version: 2}});
    });
    const request = createPayrollCommandFetch(send), input = {method: "POST", body: '{"expectedVersion":1}'};
    await expect(request("/payroll/run", input)).rejects.toThrow("Lost response");
    await request("/payroll/run", input); await request("/payroll/run", input);
    expect(request.hasAttempt("/payroll/run", input.body)).toBe(true);
    await request("/payroll/run", input);
    expect(request.hasAttempt("/payroll/run", input.body)).toBe(false);
    await request("/payroll/run", input);
    expect(new Set(seen.slice(0, 4)).size).toBe(1); expect(seen[4]).not.toBe(seen[0]);
  });
  it("separates changed payloads and Company roles while retaining exact retries", async () => {
    const dataset = {workUser: "person", workCompany: "company-A", workAssignment: "payroll-A", workRevision: "1"};
    vi.stubGlobal("document", {querySelector: () => ({dataset})});
    const seen: string[] = [], request = createPayrollCommandFetch(async (_url, init) => {seen.push(new Headers(init?.headers).get("Idempotency-Key")!); return Response.json({error: {code: "RETRY"}}, {status: 503});});
    await request("/payroll/run", {method: "POST", body: "first"}); await request("/payroll/run", {method: "POST", body: "first"});
    await request("/payroll/run", {method: "POST", body: "changed"}); dataset.workCompany = "company-B"; dataset.workAssignment = "payroll-B";
    expect(request.hasAttempt("/payroll/run", "first")).toBe(false);
    await request("/payroll/run", {method: "POST", body: "first"});
    expect(seen[1]).toBe(seen[0]); expect(seen[2]).not.toBe(seen[0]); expect(seen[3]).not.toBe(seen[0]);
  });
  it("does not acknowledge or erase later local edits from an earlier submission", async () => {
    let edit = "submitted";
    const form = {isConnected: true, getAttribute: () => edit} as unknown as HTMLFormElement, completion = {form, formEditVersion: edit};
    expect(payrollFormUnchanged(completion)).toBe(true); edit = "newer"; expect(payrollFormUnchanged(completion)).toBe(false);
    for (const missing of [undefined, null, [], {}, {id: ""}, 1, "saved"]) expect(validPayrollAcknowledgement(missing)).toBe(false);
    expect(validPayrollAcknowledgement({id: "run"})).toBe(true);
    const events: Event[] = []; vi.stubGlobal("window", {dispatchEvent: (event: Event) => {events.push(event); return true;}});
    const request = createPayrollCommandFetch(async () => Response.json({data: {id: "run", version: 2}}));
    await request("/payroll/run", {method: "POST", body: "submitted"}, completion);
    const acknowledged = events.find(event => event.type === "erpx:record-command-saved") as CustomEvent;
    expect(acknowledged.detail.formEditVersion).toBe("submitted"); expect(payrollFormUnchanged(acknowledged.detail)).toBe(false);
  });
  it("selects actual new preparation, existing settlement and history purposes", () => {
    for (const path of ["payroll/runs", "pay-groups", "payroll/advances", "payroll/thai-profiles", "country-packs", "payroll/pay-groups/group/account-mappings"]) expect(payrollCommandPurpose(path)).toBe("new-work");
    expect(payrollCommandPurpose("pay-groups/group/schedule", {enabled: true})).toBe("new-work");
    expect(payrollCommandPurpose("pay-groups/group/schedule", {enabled: false})).toBe("settle-existing");
    for (const path of ["payroll/runs/id/calculate", "payroll/runs/id/approve", "payments/batches/id/confirm", "payroll/runs/id/remit", "payroll/runs/id/adjustments"]) expect(payrollCommandPurpose(path)).toBe("settle-existing");
    expect(payrollCommandPurpose("payroll/runs/id/export-review")).toBe("history");
  });
});

const active: PayrollPurchaseControls = {newWork: true, settleExisting: true, history: true, revision: "active"};
const draining: PayrollPurchaseControls = {...active, newWork: false, revision: "draining"};
const history: PayrollPurchaseControls = {...draining, settleExisting: false, revision: "history"};
function renderPayroll<Props extends object>(Component: ComponentType<Props>, props: Props, controls?: PayrollPurchaseControls) {
  return renderToStaticMarkup(createElement(PayrollPurchaseProvider, {controls}, createElement(Component, props)));
}
describe("Payroll initial owner content and purchase controls", () => {
  it("shows new preparation only with active work and keeps disabled compatibility", () => {
    for (const controls of [undefined, active]) expect(renderPayroll(PayrollRunEditor, {base: "/holdings/acme", groups: []}, controls)).toContain("Create payroll run");
    for (const controls of [draining, history]) expect(renderPayroll(PayrollRunEditor, {base: "/holdings/acme", groups: []}, controls)).not.toContain("Create payroll run");
    expect(payrollActionAllowed(draining, "settle-existing")).toBe(true); expect(payrollActionAllowed(history, "settle-existing")).toBe(false);
  });
  it("renders current readiness from the server snapshot and hides mutation actions for retained history", () => {
    const initial = {runId: "run", version: 3, status: "preview", inputDigest: "opaque", readyToCalculate: true, readyToSubmit: true, readyToApprove: false, sourceFresh: true, blockers: []};
    const props = {base: "/holdings/acme", runId: "run", version: 3, userId: "person", canPrepare: true, canApprove: true, canExport: true, simulationMode: false, initial};
    const settling = renderPayroll(PayrollReadinessPanel, props, draining);
    expect(settling).toContain("Source inputs match the preview"); expect(settling).toContain("Submit for review"); expect(settling).not.toContain("Checking source data");
    const retained = renderPayroll(PayrollReadinessPanel, props, history);
    expect(retained).not.toContain("Submit for review"); expect(retained).toContain("Export review report");
    expect(payrollSnapshotMatches(initial, "run", 3)).toBe(true); expect(payrollSnapshotMatches(initial, "foreign", 3)).toBe(false); expect(payrollSnapshotMatches(initial, "run", 4)).toBe(false);
  });
  it("retains posted payment and remittance obligations in draining but suppresses actions in history", () => {
    const props = {base: "/holdings/acme", run: {id: "run", status: "posted"}, batch: null, items: [], userId: "person", canPrepare: true, canApprove: true, canExport: true, canConfirm: true};
    expect(renderPayroll(PayrollPaymentPanel, props, draining)).toContain("Prepare payment batch");
    expect(renderPayroll(PayrollPaymentPanel, props, history)).not.toContain("Prepare payment batch");
    const liabilities = {runId: "run", runVersion: 3, currency: "THB", obligations: [{kind: "withholding_tax" as const, accountId: "tax", accruedMinor: 10000, remittedMinor: 1000, outstandingMinor: 9000}]};
    const view = {base: "/holdings/acme", runId: "run", version: 3, userId: "person", initial: liabilities};
    const settling = renderPayroll(PayrollLiabilitiesPanel, view, draining); expect(settling).toContain("Record remittance"); expect(settling).not.toContain("Loading liabilities");
    expect(renderPayroll(PayrollLiabilitiesPanel, view, history)).not.toContain("Record remittance");
  });
  it("keeps independently reviewable mappings while closing creation during draining", () => {
    const props = {base: "/holdings/acme", groups: [{id: "group", name: "Monthly", currency: "THB"}], userId: "reviewer", options: {charts: [], periods: [], accounts: [], mappings: [{id: "mapping", pay_group_id: "group", status: "draft", created_by: "maker", version: 1}]}};
    const settling = renderPayroll(PayrollAccountMappingSettings, props, draining);
    expect(settling).toContain("Approve mapping"); expect(settling).not.toContain("Save mapping draft");
    const retained = renderPayroll(PayrollAccountMappingSettings, props, history); expect(retained).not.toContain("Approve mapping"); expect(retained).toContain("draft");
    for (const secret of ["company_package_grants", "sourceEventId", "iam.permissions"]) expect(retained).not.toContain(secret);
  });
});

